From 07a6913bffe9dbadfaa8fca36c8cc2e45afe8f68 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:52:34 +0100
Subject: [PATCH] lockscreen: show the password prompt after waking from sleep

After resuming, the lock screen only showed the clock, and the prompt
appeared only on input or when PAM happened to send a message in time.
Now it is shown on resume and fades out after the usual timeout.

BUG: 404063
---
 desktoppackage/contents/lockscreen/LockScreenUi.qml | 3 +++
 1 file changed, 3 insertions(+)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index 065a33c131..6ad0ebb795 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -128,6 +128,9 @@ Item {
         function onAboutToSuspend() {
             root.clearPassword();
         }
+        function onResumingFromSuspend() {
+            lockScreenRoot.uiVisible = true;
+        }
     }

     RejectPasswordAnimation {
-- 
